public void toSource(final CodeBuilder cb,
                       final int inputSeqNum,
                       final Node root) {
    runInCompilerThread(new Callable<Void>() {
      @Override
      public Void call() throws Exception {
        // Pre-conditions and null checks for Compiler fields
        if (options == null) {
          throw new IllegalStateException("Compiler options must be initialized before calling toSource.");
        }

        // Input delimiter handling
        if (options.printInputDelimiter) {
          if ((cb.getLength() > 0) && !cb.endsWith("\n")) {
            cb.append("\n");  // Ensure delimiter starts on a new line if content already exists
          }

          // Validate root type for delimiter context
          Preconditions.checkState(root.getType() == Token.SCRIPT,
              "Root node must be of type SCRIPT when input delimiter is enabled.");

          String delimiter = options.inputDelimiter;
          if (delimiter == null) {
            // Provide a default or throw an error if inputDelimiter is expected to be non-null
            delimiter = "// Input %name% (file %num%)"; // Example default
            // Or: throw new IllegalStateException("options.inputDelimiter cannot be null when printInputDelimiter is true.");
          }

          String sourceName = (String) root.getProp(Node.SOURCENAME_PROP);
          Preconditions.checkState(sourceName != null && !sourceName.isEmpty(),
              "Source name property (Node.SOURCENAME_PROP) must be present and non-empty for SCRIPT node.");

          // Replace placeholders in the delimiter
          delimiter = delimiter.replaceAll("%name%", sourceName)
            .replaceAll("%num%", String.valueOf(inputSeqNum));

          cb.append(delimiter)
            .append("\n");
        }

        // License comment handling
        if (root.getJSDocInfo() != null) {
          String licenseText = root.getJSDocInfo().getLicense();
          if (licenseText != null && !licenseText.isEmpty()) {
            // Sanitize license text to prevent premature comment closure
            licenseText = licenseText.replace("*/", "* /"); // Add a space to break the sequence
            cb.append("/*\n")
              .append(licenseText)
              .append("*/\n");
          }
        }

        // Source map position setting
        if (options.sourceMapOutputPath != null) {
          if (sourceMap == null) {
            throw new IllegalStateException("Source map must be initialized when sourceMapOutputPath is set.");
          }
          sourceMap.setStartingPosition(
              cb.getLineIndex(), cb.getColumnIndex());
        }

        // Generate the actual JavaScript code from the AST
        String code = toSource(root, sourceMap); // This internal method should handle 'use strict' if applicable
        if (code == null) {
            // Handle cases where toSource might return null, though unlikely for a String return type
            // Log a warning or throw an exception if this is an unexpected state.
            // For now, we'll treat it as an empty string to avoid NPEs.
            code = "";
        }

        if (!code.isEmpty()) {
          cb.append(code);

          // Ensure the output ends with a semicolon to prevent concatenation issues
          int length = code.length();
          char lastChar = code.charAt(length - 1);
          char secondLastChar = length >= 2 ?
              code.charAt(length - 2) : '\0';
          boolean hasSemiColon = lastChar == ';' ||
              (lastChar == '\n' && secondLastChar == ';');
          if (!hasSemiColon) {
            cb.append(";");
          }
        }
        return null;
      }
    });
  }
