import java.io.InputStream;

public class IOUtils { // Assuming this is the class context
    private static final int SKIP_BUF_SIZE = 4096; // From the provided context

    public static long skip(InputStream input, long numToSkip) throws IOException {
        if (input == null) {
            throw new IllegalArgumentException("InputStream cannot be null.");
        }
        if (numToSkip < 0) {
            return 0; // Skipping a negative amount means skipping nothing.
        }

        long totalSkipped = 0;
        byte[] skipBuffer = null; // Initialize lazily if needed

        while (totalSkipped < numToSkip) {
            long remaining = numToSkip - totalSkipped;
            long skipped = 0;

            try {
                skipped = input.skip(remaining);
            } catch (IOException e) {
                // If skip fails, try reading into a buffer as a fallback
                // This handles cases where skip() might not be fully supported or throws an exception
                // before reaching the end of the stream.
                if (skipBuffer == null) {
                    skipBuffer = new byte[SKIP_BUF_SIZE];
                }
