public static String sanitize(String s) {
    if (s == null) {
        return null; // Or throw IllegalArgumentException, depending on desired contract
    }

    final int len = s.length();
    final StringBuilder sb = new StringBuilder(len); // Pre-allocate capacity for efficiency

    for (int i = 0; i < len; ) {
        final int codePoint = s.codePointAt(i);

        // Check for ISO control characters
        if (Character.isISOControl(codePoint)) {
            sb.append('?');
        } else {
            // Check for Unicode SPECIALS block
            Character.UnicodeBlock block = Character.UnicodeBlock.of(codePoint);
            if (block != null && block != Character.UnicodeBlock.SPECIALS) {
                // Additionally, consider common filesystem invalid characters for archive context
