    @Override
    public void writeNumber(String encodedValue) throws IOException {
        /* 03-Dec-2010, tatu: related to [JACKSON-423], should try to keep as numeric
         *   identity as long as possible
         */
        if (encodedValue == null) {
            // As per JsonGenerator contract, null for numbers should typically be written as null token
            // or throw an exception if null is not allowed for a number.
            // Given TokenBuffer's role, writing VALUE_NULL is a reasonable default.
            _append(JsonToken.VALUE_NULL);
            return;
        }
        // Attempt to parse the string to ensure it's a valid number.
        // This helps catch malformed input early rather than during parsing from the buffer.
        // Using BigDecimal to handle arbitrary precision and avoid float/double precision issues
        // if the string represents a very large/small or precise number.
        try {
            // Attempt to parse as BigDecimal to validate numeric format.
            // This also aligns with the comment "keep as numeric identity as long as possible".
            // If it's a valid number string, we store it as a string, but with the float token type.
            // The actual BigDecimal object is not stored here, only its string representation.
            // The check is purely for validation.
            new BigDecimal(encodedValue);
        } catch (NumberFormatException e) {
            // If the string is not a valid number, throw an IOException.
            // This aligns with the JsonGenerator contract for invalid input.
            throw new IOException("Invalid numeric value: '" + encodedValue + "'", e);
        }

        // If validation passes, append it as a float number token.
        _append(JsonToken.VALUE_NUMBER_FLOAT, encodedValue);
    }

