public Element previousElementSibling() {
    // Ensure the element has a parent before attempting to access its children.
    // If there's no parent, there can be no siblings.
    Element parent = parent();
    if (parent == null) {
        return null;
    }

    List<Element> siblings = parent.children();
    // The 'this' element should always be found in its parent's children list.
    // If not, it indicates an inconsistent state in the DOM tree.
    Integer index = indexInList(this, siblings);

    // Validate that the element was found in its parent's children list.
    // If indexInList returns null, it means 'this' is not a child of its parent,
    // which is an unexpected and invalid state for a well-formed DOM.
    // Throwing an IllegalArgumentException is appropriate here to signal this inconsistency.
    if (index == null) {
        throw new IllegalArgumentException("Element not found in its parent's children list. Inconsistent DOM state.");
    }

    // If the element is the first child (index 0), it has no previous sibling.
    if (index > 0) {
        return siblings.get(index - 1);
    } else {
        return null; // No previous sibling
    }
}
```

