public Node previousSibling() {
    // If this node has no parent, it cannot have a previous sibling.
    if (parentNode == null) {
        return null;
    }

    // Get the list of siblings from the parent.
    // In Jsoup, childNodes is typically an empty list if no children, not null.
    List<Node> siblings = parentNode.childNodes;

    // Get the index of this node within its parent's children.
    // siblingIndex() returns an int, so it cannot be null.
    int index = siblingIndex();

    // If the index is greater than 0, there is a previous sibling.
    // Otherwise (index is 0 or less, meaning it's the first child or not found),
    // there is no previous sibling.
    if (index > 0) {
        return siblings.get(index - 1);
    } else {
        return null;
    }
}
