import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;

public class Complex {
    // ... (existing fields and other methods) ...

    public static final Complex I = new Complex(0.0, 1.0);
    public static final Complex NaN = new Complex(Double.NaN, Double.NaN);
    public static final Complex INF = new Complex(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
    public static final Complex ONE = new Complex(1.0, 0.0);
    public static final Complex ZERO = new Complex(0.0, 0.0);
    private static final long serialVersionUID = -6195664516687396620L;
    private final double imaginary;
    private final double real;
    private final transient boolean isNaN;
    private final transient boolean isInfinite;

    public Complex(double real) {
        this(real, 0.0);
    }

    public Complex(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
        this.isNaN = Double.isNaN(real) || Double.isNaN(imaginary);
        this.isInfinite = !isNaN && (Double.isInfinite(real) || Double.isInfinite(imaginary));
    }

    public double getReal() {
        return real;
    }

    public double getImaginary() {
        return imaginary;
    }

    public boolean isNaN() {
        return isNaN;
    }

    public boolean isInfinite() {
        return isInfinite;
    }

    protected Complex createComplex(double realPart, double imaginaryPart) {
        return new Complex(realPart, imaginaryPart);
    }

    public Complex divide(Complex divisor) throws NullArgumentException {
        MathUtils.checkNotNull(divisor);

        // Handle NaN cases first
        if (this.isNaN || divisor.isNaN) {
            return NaN;
        }

        // Handle division by zero (0 + 0i)
        if (divisor.getReal() == 0.0 && divisor.getImaginary() == 0.0) {
            return NaN; // Division by zero is undefined
        }

        // Handle infinite cases
        if (this.isInfinite()) {
            if (divisor.isInfinite()) {
                return NaN; // INF / INF is undefined
            } else {
                // INF / finite (non-zero) = INF
                return INF;
            }
        } else if (divisor.isInfinite()) {
            // finite (non-zero) / INF = 0
            return ZERO;
        }

        // Standard complex division (a + bi) / (c + di) = ((ac + bd) + i(bc - ad)) / (c^2 + d^2)
        // To avoid overflow/underflow, scale by the larger of c or d
        final double c = divisor.getReal();
        final double d = divisor.getImaginary();

        if (FastMath.abs(c) < FastMath.abs(d)) {
            double q = c / d;
            double denominator = d * (1 + q * q); // d * (1 + (c/d)^2) = d * (d^2 + c^2)/d^2 = (d^2 + c^2)/d
            return createComplex(
                (this.real * q + this.imaginary) / denominator,
                (this.imaginary * q - this.real) / denominator
            );
        } else {
            double q = d / c;
            double denominator = c * (1 + q * q); // c * (1 + (d/c)^2) = c * (c^2 + d^2)/c^2 = (c^2 + d^2)/c
            return createComplex(
                (this.real + this.imaginary * q) / denominator,
                (this.imaginary - this.real * q) / denominator
            );
        }
    }
}
