    if (tempDfp.greaterThan(currentDfp)) {
        exponent--;
    }
    // Now, 2^exponent <= currentDfp < 2^(exponent+1)

    /* We have the exponent, now work on the mantissa */

    // Normalize currentDfp to be between 1 and 2 (or 0 and 1 for subnormals)
    currentDfp = currentDfp.divide(DfpMath.pow(getTwo(), exponent));

    // Handle special cases for double representation
    if (exponent < -1074) { // Too small to be represented even as subnormal
        return negate ? -0.0 : 0.0; // Return signed zero
    }

    if (exponent > 1023) { // Too large, overflows to infinity
        return negate ? Double.NEGATIVE_INFINITY : Double.POSITIVE_INFINITY;
    }

    // Remove the implicit leading '1' for normal numbers
    // For subnormal numbers, the exponent will be -1023, and the mantissa will be < 1
    if (exponent > -1023) {
        currentDfp = currentDfp.subtract(getOne());
    }

    // Scale the mantissa to fit into 52 bits and round
    // 2^52 = 4503599627370496L
    currentDfp = currentDfp.multiply(newInstance(4503599627370496L)).rint();

    // Extract the mantissa as a long. Assuming Dfp.longValue() is available and precise after rint().
    long mantissa = currentDfp.longValue(); // More robust than string conversion

