        // We need to shift the mantissa right by (1023 + exponent) to get the correct subnormal mantissa.
        // Example: if Dfp exponent is -1023, double exponent is 0, mantissa is 1.0.
        // If Dfp exponent is -1024, double exponent is 0, mantissa is 0.5.
        // The loop below effectively does this.
        while (exponent < -1022) { // Loop until Dfp exponent corresponds to double's effective -1022
            mantissa >>>= 1;
            exponent++;
        }
