public static long safeMultiply(long val1, int val2) {
    // Handle common cases and edge cases for val2 to optimize and prevent specific overflows
    switch (val2) {
        case -1:
            // Special handling for Long.MIN_VALUE * -1 which overflows
            if (val1 == Long.MIN_VALUE) {
                throw new ArithmeticException("Multiplication overflows a long: " + val1 + " * " + val2);
            }
            return -val1;
        case 0:
            return 0L;
        case 1:
            return val1;
    }

    // Check for overflow before performing the multiplication for other val2 values
    // This approach avoids the division-based check which can have its own issues (e.g., division by zero, precision)
    // and is generally more robust for integer overflow detection.
    if (val1 > 0) { // val1 is positive
        if (val2 > 0) { // val2 is positive
            if (val1 > Long.MAX_VALUE / val2) {
                throw new ArithmeticException("Multiplication overflows a long: " + val1 + " * " + val2);
            }
        } else { // val2 is negative
            if (val2 < Long.MIN_VALUE / val1) { // Note: Long.MIN_VALUE / positive_val1 is negative
                throw new ArithmeticException("Multiplication overflows a long: " + val1 + " * " + val2);
            }
        }
    } else { // val1 is negative or zero
        if (val2 > 0) { // val2 is positive
            if (val1 < Long.MIN_VALUE / val2) { // Note: Long.MIN_VALUE / positive_val2 is negative
                throw new ArithmeticException("Multiplication overflows a long: " + val1 + " * " + val2);
            }
        } else { // val2 is negative
            // Both val1 and val2 are negative. Result should be positive.
            // Special case: if val1 is Long.MIN_VALUE and val2 is -1, it's handled above.
            // For other negative val2, if val1 is negative, then val1 / val2 will be positive.
            // We need to check if val1 is less than Long.MAX_VALUE / val2 (which is negative)
            // This check is tricky. A more direct way is to check if val1 * val2 would exceed Long.MAX_VALUE.
            // If val1 is negative and val2 is negative, then val1 * val2 is positive.
            // The check should be: if val1 < Long.MAX_VALUE / val2 (where val2 is negative, so Long.MAX_VALUE / val2 is negative)
            // This is equivalent to checking if val1 * val2 > Long.MAX_VALUE.
            // Example: val1 = -922337203685477580L, val2 = -10. Result is 9223372036854775800L (overflow)
            // Long.MAX_VALUE / -10 = -922337203685477580
            // -922337203685477580L < -922337203685477580 (false)
            // The check should be: if val1 < Long.MAX_VALUE / val2 (when val2 is negative, Long.MAX_VALUE / val2 is negative)
            // This is correct.
            if (val1 < Long.MAX_VALUE / val2) {
                throw new ArithmeticException("Multiplication overflows a long: " + val1 + " * " + val2);
            }
        }
    }

    // If no overflow detected, perform the multiplication
    return val1 * val2;
}
